To avoid concatenating `conditions, extensions, mainFields`, we can keep track of yet another object map like this:

```ts
const objectKeyMap = new WeakMap<object, string>();

function getOptionObjectKey(key: object) {
  let value = objectKeyMap.get(key);
  if (!value) {
    value = Math.random().toString(36).slice(2);
    objectKeyMap.set(key, value);
  }
  return value;
}

function getResolveCacheKey(key: string, options: InternalResolveOptions) {
    return (
      key
      + '|' + (options.webCompatible ? '1' : '0')
      + '|' + (options.isRequire ? '1' : '0')
      + '|' + getOptionObjectKey(options.conditions)
      + '|' + getOptionObjectKey(options.extensions)
      + '|' + getOptionObjectKey(options.mainFields)
    )
}
```

This seems to help a lot though I'm not sure how much of optimization is the goal since this is still a fraction of the entire `resolveId` 80000 times.

